{
  "correction_rules": [
    "Reduce forecast bias when sentiment history shows negative sentiment (e.g., -0.25 or 0.00) — model tends to overreact and overshoot downward.",
    "Apply mean reversion correction: if forecast is > 10% above recent 5-day average, reduce by 5–10% to align with observed downward drift.",
    "After sharp price spikes (e.g., >10% from prior day), reduce forecast by 5–15% to avoid overcorrection or overshoot.",
    "When sentiment history includes 0.50 (neutral to slightly bullish), slightly increase forecast to avoid underestimating rebound potential.",
    "For 30-day forecasts, reduce early-period (first 5 days) forecast values by 5–10% if recent history shows downward momentum or negative sentiment.",
    "If true outcome is consistently below forecast (e.g., 3–5% gap over 5+ days), apply downward adjustment of 2–5% per day to reflect persistent underperformance."
  ]
}
